require_once __DIR__ . '/../includes/config.php';
require_role(['student','host','coordinator']);db_required();$events=$pdo->query("SELECT id,title,event_date FROM events WHERE status='approved' AND event_date>=NOW() ORDER BY event_date")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT IGNORE INTO coordinator_applications(user_id,event_id,note,status) VALUES(?,?,?,\'pending\')');$s->execute([current_user()['id'],(int)$_POST['event_id'],trim($_POST['note'])]);flash('success','Coordinator application sent to the HOD.');redirect('/coordinator/dashboard.php');}$page_title='Coordinator';require __DIR__.'/../includes/header.php';?><div class="container py-5"><div class="row justify-content-center"><div class="col-lg-8"><div class="hero-mini mb-4"><div class="section-kicker text-info">Lead</div><h2 class="fw-bold">Become an event coordinator.</h2><p class="text-white-50">Take ownership of schedules, teams and event execution.</p></div><div class="dash-card p-4"><form method="post"><label class="form-label">Event</label><select name="event_id" class="form-select mb-3" required><?php foreach($events as $e):?><option value="<?=$e['id']?>"><?=e($e['title'])?> · <?=date('d M',strtotime($e['event_date']))?></option><?php endforeach;?></select><label class="form-label">Why are you a good coordinator?</label><textarea name="note" class="form-control mb-3" rows="5" required placeholder="Leadership, communication, event experience..."></textarea><button class="btn btn-primary rounded-pill">Submit coordinator application</button></form></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
